-- 46-inserir-pecas-novas-favoritas.sql
-- Insere 239 peças encontradas nas NFes do ML que NÃO existiam no estoque.
-- Todas marcadas como favorito=true (foram compradas, terão saída).
-- qtd_atual = 0 (não está adicionando estoque, apenas catalogando).

ON CONFLICT (sku) DO UPDATE SET
  favorito = true,
  deleted_at = NULL;

-- Verificação
SELECT COUNT(*) AS total_favoritos FROM peca WHERE favorito = true;
